<?php /* Template Name: AMIA Dashboard */ get_header(); get_template_part( 'partials/dashboard-shell' ); $stats = amia_premium_agum_stats(); ?><h1>Dashboard</h1><div class="amia-stat-grid"><div class="amia-stat"><span>Total Users</span><strong><?php echo esc_html( $stats['total'] ); ?></strong></div><div class="amia-stat"><span>Students</span><strong><?php echo esc_html( $stats['students'] ); ?></strong></div><div class="amia-stat"><span>Ustads</span><strong><?php echo esc_html( $stats['ustads'] ); ?></strong></div><div class="amia-stat"><span>Images</span><strong><?php echo esc_html( $stats['images'] ); ?></strong></div></div><?php $amia_notifications = amia_premium_agum_notifications( 6 ); if ( $amia_notifications ) : ?><section class="amia-notifications"><h2>Live Notifications</h2><?php foreach ( $amia_notifications as $notice ) : ?><article><strong><?php echo esc_html( $notice->title ); ?></strong><p><?php echo esc_html( $notice->message ); ?></p><small><?php echo esc_html( $notice->time_ago ); ?></small></article><?php endforeach; ?></section><?php endif; ?><?php get_template_part( 'partials/activity-list' ); get_template_part( 'partials/dashboard-end' ); get_footer(); ?>
